frappe.ui.form.on('Payment Entry', {
	refresh(frm) {
		if(frm.doc.party_type =='Customer'){
            frappe.call({
            	method: 'frappe.client.get_list',
            	args: {
            	    doctype: "Sales Invoice",
            	    fields:["name","posting_date","customer","rounded_total","outstanding_amount"],
            	    filters:[["docstatus","=",1], ["customer","=",frm.doc.party], ["outstanding_amount",">",0]] 
            	},
            	async:false,
            	callback(r) {
            	    //frappe.msgprint("Just Look Console");
            	     if(r.message){
                        let outstandings = r.message
                        if(outstandings.length == 0){
                            frappe.msgprint("No Bills Pending. Relax!!!");
                        }
                        else{
                            for(let i = 0;i<outstandings.length;i++){
                                frappe.msgprint(frappe.datetime.get_day_diff(frappe.datetime.get_today(),outstandings[i].posting_date)+ ' days is due for '+ outstandings[i].name);
                      		    frm.add_custom_button(outstandings[i].name, function(){ frappe.msgprint('Outstanding Amount',outstandings[i].outstanding_amount) }
                      		    , __("Outstanding"));
          		            }
                        }
                    }
            	}
            })
        }
	},
	onload(frm) {
        if(frm.doc.party_type =='Customer'){
            frappe.call({
            	method: 'frappe.client.get_list',
            	args: {
            	    doctype: "Sales Invoice",
            	    fields:["name","posting_date","customer","rounded_total","outstanding_amount"],
            	    filters:[["docstatus","=",1], ["customer","=",frm.doc.party], ["outstanding_amount",">",0]] 
            	},
            	async:false,
            	callback(r) {
            	    //frappe.msgprint("Just Look Console");
            	     if(r.message){
                        let outstandings = r.message
                        if(outstandings.length == 0){
                            frappe.msgprint("No Bills Pending. Relax!!!");
                        }
                        else{
                            for(let i = 0;i<outstandings.length;i++){
                                frappe.msgprint(frappe.datetime.get_day_diff(frappe.datetime.get_today(),outstandings[i].posting_date)+ ' days is due for '+ outstandings[i].name);
                      		    frm.add_custom_button(outstandings[i].name, function(){ frappe.msgprint('Outstanding Amount',outstandings[i].outstanding_amount) }
                      		    , __("Outstanding"));
          		            }
                        }
                    }
            	}
            })
        }
    },
    before_save(frm){
        if(frm.doc.paid_to==="Bank Account - SE-K"){
            frappe.throw(__('Bank Account - SE-K is not a valid account. Please select proper Company Account '))
            frm.set_value('paid_to','')
            frm.set_df_property('bank_account', 'reqd', 1)
        }
        if(frm.doc.paid_from==="Bank Account - SE-K"){
            frappe.throw(__('Bank Account - SE-K is not a valid account. Please select proper Company Account '))
            frm.set_value('paid_from','')
            frm.set_df_property('bank_account', 'reqd', 1)
        }
    }
})
frappe.ui.form.on('Payment Entry', 'mode_of_payment', function(frm){
    if(frm.doc.mode_of_payment === 'NEFT'||frm.doc.mode_of_payment === 'UPI'){
        frm.set_df_property('bank_account', 'reqd', 1)
        frm.set_df_property('reference_no','reqd',1)
        frm.set_df_property('reference_date','reqd',1)
    }
    if(frm.doc.mode_of_payment === 'Cheque'){
        frm.set_df_property('reference_no','reqd',1)
        frm.set_df_property('reference_date','reqd',1)
    }
})

frappe.ui.form.on("Sales Invoice", {
	setup(frm) {
		frm.set_query("custom_transporter", () => {
			return {
				filters: {
					"is_transporter": 1
				}
			};
		});
		frm.set_query("transporter", () => {
			return {
				filters: {
					"is_transporter": 1
				}
			};
		});
		frm.set_query("custom_transporter_from_address", () => {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.custom_transporter
				}
			};
		});
		frm.set_query("custom_transporter_to_address", () => {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.custom_transporter
				}
			};
		});
	},
	refresh(frm) {
		frm.set_query("custom_transporter", () => {
			return {
				filters: {
					"is_transporter": 1
				}
			};
		});
		frm.set_query("transporter", () => {
			return {
				filters: {
					"is_transporter": 1
				}
			};
		});
		frm.set_query("custom_transporter_from_address", () => {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.custom_transporter
				}
			};
		});
		frm.set_query("custom_transporter_to_address", () => {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.custom_transporter
				}
			};
		});
	},
	onload(frm) {
		frappe.call({
			method: "frappe.client.get_list",
			args: {
				doctype: "Sales Invoice",
				fields: ["name", "posting_date", "customer", "rounded_total", "outstanding_amount"],
				filters: [["docstatus", "=", 1], ["customer", "=", frm.doc.customer], ["outstanding_amount", ">", 0]]
			},
			async: false,
			callback(r) {
				if (r.message) {
					let outstandings = r.message;
					for (let i = 0; i < outstandings.length; i++) {
						if (frappe.datetime.get_day_diff(frappe.datetime.get_today(), outstandings[i].posting_date) != 0) {
							frappe.msgprint(frappe.datetime.get_day_diff(frappe.datetime.get_today(), outstandings[i].posting_date) + " days is due for " + outstandings[i].name);
						}
						frm.add_custom_button(outstandings[i].name, function() {
							frappe.msgprint("Outstanding Amount", outstandings[i].outstanding_amount);
						}, __("Outstanding"));
					}
				}
			}
		});
		if (frm.doc.status == "Draft") {
			frm.doc.update_stock = 1;
			frm.refresh_field("update_stock");
		}
		if (frm.doc.company == "Sravi Enterprises - Kolapakkam") {
			frm.doc.set_warehouse = "Stores - SE-K";
			frm.refresh_field("set_warehouse");
		}
		frm.doc.apply_discount_on = "Grand Total";
		frm.refresh_field("apply_discount_on");
	},
	custom_transporter(frm) {
		if (!frm.doc.custom_transporter) {
			frm.set_value("custom_transporter_from_address", "");
			frm.set_value("custom_transporter_from_address_display", "");
			frm.set_value("custom_transporter_to_address", "");
			frm.set_value("custom_transporter_to_address_display", "");
		} else {
			frappe.call({
				method: "frappe.contacts.doctype.address.address.get_default_address",
				args: {
					doctype: "Supplier",
					name: frm.doc.custom_transporter
				},
				callback(r) {
					if (r.message) {
						frm.set_value("custom_transporter_from_address", r.message);
					}
				}
			});
		}
	},
	custom_transporter_from_address(frm) {
		if (frm.doc.custom_transporter_from_address) {
			frappe.call({
				method: "frappe.contacts.doctype.address.address.get_address_display",
				args: {
					address_dict: frm.doc.custom_transporter_from_address
				},
				callback(r) {
					let formatted = (r.message || "").replace(/<br\s*[/]?>/gi, "\n").replace(/\n+/g, "\n").trim();
					frm.set_value("custom_transporter_from_address_display", formatted);
				}
			});
		} else {
			frm.set_value("custom_transporter_from_address_display", "");
		}
	},
	custom_is_godown_delivery(frm) {
		if (!frm.doc.custom_is_godown_delivery) {
			frm.set_value("custom_transporter_to_address", "");
			frm.set_value("custom_transporter_to_address_display", "");
		}
	},
	custom_transporter_to_address(frm) {
		if (frm.doc.custom_transporter_to_address) {
			frappe.call({
				method: "frappe.contacts.doctype.address.address.get_address_display",
				args: {
					address_dict: frm.doc.custom_transporter_to_address
				},
				callback(r) {
					let formatted = (r.message || "").replace(/<br\s*[/]?>/gi, "\n").replace(/\n+/g, "\n").trim();
					frm.set_value("custom_transporter_to_address_display", formatted);
				}
			});
		} else {
			frm.set_value("custom_transporter_to_address_display", "");
		}
	}
});

frappe.ui.form.on('Purchase Invoice', {
	refresh(frm) {
